style.css:
/* Pink Once Upon a Marvel — Disney+ */

body {
  background-color: #f4dce2 !important;
  color: #74505b !important;
  font-family: Georgia, serif !important;
}

/* Rosa palo */
main, section, header, footer {
  background-color: #f9e5e9 !important;
}

/* Títulos vintage */
h1, h2, h3, h4 {
  color: #d9a5b3 !important;
  text-shadow: 0 0 5px #c5a45e !important;
}

/* Enlaces */
a {
  color: #bd9858 !important;
}

/* Botones y flechitas */
button {
  background-color: #f9e5e9 !important;
  color: #a87888 !important;
  border: 1px solid #c5a45e !important;
  border-radius: 20px !important;
}

/* Detalles delicados */
button:hover {
  box-shadow: 0 0 10px #d9a5b3 !important;
}

/* Imágenes */
img {
  border-radius: 12px !important;
}

/* Selección rosa */
::selection {
  background-color: #d9a5b3 !important;
  color: white !important;
}
